head.script:
// https://inswave01.atlassian.net/browse/WAEA-920



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setDrillDownDragDrop]<br/>GridView 에 DrillDown 이 적용되었을때 Drag&Drop 으로 데이터 이동을 허용할지 설정합니다.",
    "validation" : [
        "inputType='drillDown' 인 Column 이 정의되어 있고, dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성 중 하나 이상 true 여야 동작합니다.",
        "value(필수) 파라미터를 true 로 설정 시 Drag&Drop 으로 데이터 이동을 허용합니다.",
        "value(필수) 파라미터를 false 로 설정 시 Drag&Drop 으로 데이터 이동을 허용하지 않습니다.",
        "DrillDown 이 적용된 GridView 에서 Drag&Drop 을 활성화 하려면 해당 메소드를 사용해야하며 속성은 제공되지 않습니다.",
        "DrillDown 이 적용된 GridView 에서 해당 메소드로 Drag&Drop 을 활성화 하지 않으면 Drag 와 Drop 모두 동작하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 — DrillDown(계층형) + dataDragDrop=true 고정 GridView 구성
//  - drilldown 컬럼(name) + depthColumn(depth) 로 3단계(본부 depth1 > 팀 depth2 > 사원 depth3) 계층 표현. showDepth=1 → 초기 본부만 표시.
//  - dataDragDrop=true 고정(전제: dataDragDrop 계열 중 하나 이상 true). + dataDragDropSelf=true 로 동일 그리드 내 노드 이동 허용.
//  - 단, DrillDown 적용 그리드는 setDrillDownDragDrop(true) 미호출 상태에서는 Drag/Drop 모두 동작하지 않음(초기 미호출).
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof dlt_bind !== 'undefined') { $p.data.remove("dlt_bind"); }

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="DrillDown 그리드 + dataDragDrop=true 전제. DrillDown 은 [setDrillDownDragDrop] 로 활성(true)해야만 Drag/Drop 동작(false/미호출 시 모두 안 됨). 행을 Drag&Drop 으로 이동해 확인하고, 설정값은 내부 플래그(drillDownDragDrop)로 확인."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // === 바인딩 DataList(dlt_bind) ===
    //  - depth : 계층 깊이(number). 1=부모, 2=자식. drilldown 컬럼의 depthColumn 으로 사용
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 계층 데이터 : 3단계(본부 depth1 > 팀 depth2 > 사원 depth3). 부모 바로 아래에 그 자식이 위치(엔진 drilldown 은 순서 기반)
    let jsonData = [
        { "name": "영업본부",     "dept": "Sales", "depth": 1 },
        { "name": "  영업1팀",    "dept": "Sales", "depth": 2 },
        { "name": "    김영업",   "dept": "Sales", "depth": 3 },
        { "name": "    이영업",   "dept": "Sales", "depth": 3 },
        { "name": "개발본부",     "dept": "Dev",   "depth": 1 },
        { "name": "  개발1팀",    "dept": "Dev",   "depth": 2 },
        { "name": "    박개발",   "dept": "Dev",   "depth": 3 },
        { "name": "    최개발",   "dept": "Dev",   "depth": 3 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (공통 createCList)
    //  - dataDragDrop=true (전제 조건), dataDragDropSelf=true (동일 그리드 내 이동 허용)
    let properties = {
        dataList: "data:dlt_bind",
        dataDragDrop: true,
        dataDragDropSelf: true,
        checkAllType: "false"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    // target 생성 — name 컬럼을 inputType="drilldown" + depthColumn="depth" + showDepth="1" + depthStartIndex="1"
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;" ev:ondatadragstart="scwin.target1_ondatadragstart" ev:ondatadrop="scwin.target1_ondatadrop">';
    strTarget += '<w2:caption style="" id="caption1" value="setDrillDownDragDrop DrillDown 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol1" value="이름(DrillDown)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="depth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // name : DrillDown 컬럼 (계층 토글 컬럼)
    strTarget += '<w2:column width="200" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="depth" dataList="depth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 설정 결과 확인 출력 (초기: 미호출 상태)
    scwin.btn_setDrillDownDragDrop_onclick();
};



// [setDrillDownDragDrop] : par_value 값(true/false)을 Boolean 으로 target1 에 적용
//  - 쌍 get 메소드가 없으므로(엔진 미제공) 설정 직후 내부 플래그(drillDownDragDrop)로 반영 여부 확인 (§5 set 검증 규칙)
scwin.btn_setDrillDownDragDrop_onclick = function () {
    let value = par_value.getText() === "true";

    target1.setDrillDownDragDrop(value);

    let b = wf_body_bottom.getObj("scwin");
    b.setReturnValue("setDrillDownDragDrop(" + value + ") 호출");
    b.setReturnValue("적용된 drillDownDragDrop 내부 플래그 : " + target1.drillDownDragDrop);
};



// 전체 펼치기/숨기기 토글 — 현재 전부 펼쳐졌으면 모두 접고, 아니면 모두 펼침
//  - 접힌/펼친 부모 판정: 자식 있음(getChildrenRowIndexArray>0) + 다음 표시행 depth 비교(자식이 보이면 펼침, 안 보이면 접힘)
scwin.btn_expandAll_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let guard = 0;
    if (target1.getRowCount() >= target1.getTotalRow()) {
        // [전체 숨기기] : 펼쳐진 부모를 접음 (상위 접으면 하위 전체 숨김)
        let found = true;
        while (found && guard < 300) {
            guard++; found = false;
            for (let i = 0; i < target1.getRowCount(); i++) {
                if (target1.getChildrenRowIndexArray(target1.getRealRowIndex(i)).length > 0) {
                    let cur = Number(target1.getCellData(i, "depth"));
                    let next = (i + 1 < target1.getRowCount()) ? Number(target1.getCellData(i + 1, "depth")) : -1;
                    if (next > cur) { target1.toggle(i); found = true; break; }  // 펼쳐짐 → 접기
                }
            }
        }
        b.setReturnValue("[전체 숨기기] 표시 Row 수 : " + target1.getRowCount());
    } else {
        // [전체 펼치기] : 표시 순서대로 내려가며 접힌 부모를 펼침
        let i = 0;
        while (i < target1.getRowCount() && guard < 300) {
            guard++;
            if (target1.getChildrenRowIndexArray(target1.getRealRowIndex(i)).length > 0) {
                let cur = Number(target1.getCellData(i, "depth"));
                let next = (i + 1 < target1.getRowCount()) ? Number(target1.getCellData(i + 1, "depth")) : -1;
                if (next <= cur) { target1.toggle(i); continue; }  // 접힘 → 펼치기
            }
            i++;
        }
        b.setReturnValue("[전체 펼치기] 표시 Row 수 : " + target1.getRowCount());
    }
};



// [데이터 출력] : '전체' Row(접혀서 화면에 안 보이는 자식 포함)를 DataList 순서대로 출력
//  - DrillDown 접힘 상태와 무관하게 DataList(dlt_bind) 전체를 트리 순서로 덤프 → 하위 요소까지 이동되었는지 검증 가능
scwin.btn_dumpData_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    // getAllJSON() : DrillDown 접힘과 무관하게 전체 데이터(접힌 자식 포함)를 트리 순서로 반환
    let arr = dlt_bind.getAllJSON();
    b.setReturnValue("===== [데이터 출력] 전체 " + arr.length + "행 (접힌 자식 포함, 트리 순서) =====");
    for (let i = 0; i < arr.length; i++) {
        b.setReturnValue("  " + i + " : name=" + arr[i].name + ", dept=" + arr[i].dept + ", depth=" + arr[i].depth);
    }
};



// Drag 시작(사용자 액션 보조 출력) : 현재 활성 상태 안내
scwin.target1_ondatadragstart = function () {
    let b = wf_body_bottom.getObj("scwin");
    b.btn_clear_onclick();
    b.setReturnValue("Drag 시작 (현재 drillDownDragDrop = " + target1.drillDownDragDrop + ")");
};

// Drop 완료 : 이동 후 데이터 순서를 출력하여 Row 이동을 검증
scwin.target1_ondatadrop = function () {
    let b = wf_body_bottom.getObj("scwin");
    b.setReturnValue("Drop 완료 - 전체 Row 수 : " + target1.getTotalRow());
    scwin.btn_dumpData_onclick();
};
